ALTER TYPE "GrowthGoalStatus" ADD VALUE 'SUGGESTED' BEFORE 'ACTIVE';
ALTER TYPE "GrowthGoalStatus" ADD VALUE 'PAUSED' AFTER 'ACTIVE';
CREATE TYPE "GrowthJournalType" AS ENUM ('NOTE', 'STEP_REFLECTION', 'POST_DATE', 'SAVED_ADVICE');
ALTER TABLE "GrowthGoal" ADD COLUMN "targetDate" TIMESTAMP(3), ADD COLUMN "source" TEXT NOT NULL DEFAULT 'MANUAL', ADD COLUMN "version" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "pathEnrollmentId" UUID;
ALTER TABLE "GrowthExercise" ADD COLUMN "goalId" UUID, ADD COLUMN "note" TEXT;
CREATE TABLE "GrowthJournalEntry" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "goalId" UUID, "type" "GrowthJournalType" NOT NULL DEFAULT 'NOTE', "title" TEXT, "content" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "GrowthJournalEntry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GrowthEvent" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "entityType" TEXT NOT NULL, "entityId" UUID, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "GrowthEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GrowthPreference" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "timezone" TEXT NOT NULL DEFAULT 'UTC', "remindersEnabled" BOOLEAN NOT NULL DEFAULT false, "reminderHour" INTEGER NOT NULL DEFAULT 19, "analyticsConsent" BOOLEAN NOT NULL DEFAULT false, "gentleStreaks" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "GrowthPreference_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GrowthPathEnrollment" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "pathKey" TEXT NOT NULL, "title" TEXT NOT NULL, "completedUnits" INTEGER NOT NULL DEFAULT 0, "totalUnits" INTEGER NOT NULL DEFAULT 5, "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "GrowthPathEnrollment_pkey" PRIMARY KEY ("id"));
CREATE INDEX "GrowthJournalEntry_userId_createdAt_idx" ON "GrowthJournalEntry"("userId", "createdAt"); CREATE INDEX "GrowthJournalEntry_goalId_createdAt_idx" ON "GrowthJournalEntry"("goalId", "createdAt");
CREATE INDEX "GrowthEvent_userId_createdAt_idx" ON "GrowthEvent"("userId", "createdAt"); CREATE UNIQUE INDEX "GrowthPreference_userId_key" ON "GrowthPreference"("userId"); CREATE UNIQUE INDEX "GrowthPathEnrollment_userId_pathKey_key" ON "GrowthPathEnrollment"("userId", "pathKey"); CREATE INDEX "GrowthPathEnrollment_userId_updatedAt_idx" ON "GrowthPathEnrollment"("userId", "updatedAt");
ALTER TABLE "GrowthGoal" ADD CONSTRAINT "GrowthGoal_pathEnrollmentId_fkey" FOREIGN KEY ("pathEnrollmentId") REFERENCES "GrowthPathEnrollment"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "GrowthExercise" ADD CONSTRAINT "GrowthExercise_goalId_fkey" FOREIGN KEY ("goalId") REFERENCES "GrowthGoal"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "GrowthJournalEntry" ADD CONSTRAINT "GrowthJournalEntry_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "GrowthJournalEntry" ADD CONSTRAINT "GrowthJournalEntry_goalId_fkey" FOREIGN KEY ("goalId") REFERENCES "GrowthGoal"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "GrowthEvent" ADD CONSTRAINT "GrowthEvent_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "GrowthPreference" ADD CONSTRAINT "GrowthPreference_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "GrowthPathEnrollment" ADD CONSTRAINT "GrowthPathEnrollment_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
